/* ---------------- CompanyManager ---------------- */
const CompanyManager = ({ companyGuid, setCompanyGuid }) => {
  const [companies, setCompanies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [newGuid, setNewGuid] = useState('');
  const [newName, setNewName] = useState('');
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    fetchCompanies();
  }, []);

  const fetchCompanies = async () => {
    setLoading(true);
    try {
      const res = await api.get('/company');
      if (res.success) {
        setCompanies(res.data || []);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSetActive = async (guid) => {
    try {
      const res = await api.post('/company/set-active', { company_guid: guid });
      if (res.success) {
        setCompanyGuid(res.company_guid);
      }
    } catch (err) {
      alert(err.message || 'Failed to set active company');
    }
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    if (!newGuid || !newName) return;
    setCreating(true);
    try {
      const res = await api.post('/company/create', { company_guid: newGuid, name: newName });
      if (res.success) {
        setNewGuid('');
        setNewName('');
        fetchCompanies();
      } else {
        alert(res.message || 'Failed to create company');
      }
    } catch (err) {
      alert(err.message || 'Error creating company');
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="fade-in">
      <div className="page-header">
        <div>
          <h1>Companies</h1>
          <p>Manage your companies and set the active one.</p>
        </div>
      </div>

      {error && <div style={{ color: 'var(--danger)', marginBottom: 16 }}>{error}</div>}

      <div className="grid-2">
        <div className="glass-panel">
          <h3 style={{ marginBottom: 16 }}>Add New Company</h3>
          <form onSubmit={handleCreate} style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            <input 
              type="text" 
              className="search-input" 
              placeholder="Company Name" 
              value={newName} 
              onChange={(e) => setNewName(e.target.value)} 
              required 
            />
            <input 
              type="text" 
              className="search-input" 
              placeholder="Company GUID" 
              value={newGuid} 
              onChange={(e) => setNewGuid(e.target.value)} 
              required 
            />
            <button type="submit" className="btn-primary" disabled={creating} style={{ alignSelf: 'flex-start' }}>
              {creating ? 'Adding...' : 'Add Company'}
            </button>
          </form>
        </div>

        <div className="glass-panel" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <h3 style={{ marginBottom: 16 }}>Your Companies</h3>
          {loading ? (
            <p>Loading companies...</p>
          ) : companies.length === 0 ? (
            <p>No companies found. Create one to get started.</p>
          ) : (
            companies.map(c => (
              <div key={c.company_guid} style={{ 
                padding: 16, 
                borderRadius: 12, 
                background: c.company_guid === companyGuid ? 'rgba(52, 199, 89, 0.15)' : 'rgba(0,0,0,0.03)',
                border: c.company_guid === companyGuid ? '1px solid var(--success)' : '1px solid rgba(0,0,0,0.05)',
                display: 'flex', 
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <h4 style={{ margin: '0 0 4px 0', fontSize: 16 }}>{c.name}</h4>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{c.company_guid}</div>
                </div>
                {c.company_guid === companyGuid ? (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'var(--success)', fontWeight: 600, fontSize: 13 }}>
                    <CheckCircle2 size={16} /> Active
                  </div>
                ) : (
                  <button 
                    className="btn-secondary" 
                    style={{ padding: '6px 12px', fontSize: 13 }}
                    onClick={() => handleSetActive(c.company_guid)}
                  >
                    Set Active
                  </button>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

